<template>
  <ElDialog v-for="(dialog, index) in dialogVisible" :key="index" v-model="dialogVisible[index]"
    :close-on-click-modal="false">
    <!--<div class="dialogHeader absolute">遊戲幣走向</div>-->
    <div class="dialogBody">
      <div>
        <Line :id="`my-chart-${index}`" :options="chartOptions" :data="chartDataComputed[index]" />
      </div>
      <div class="flex justify-end mt-5">
        <ElButton class="agreeBtn" type="primary" @click="dialogVisible[index] = false">
          關閉
        </ElButton>
      </div>
    </div>
  </ElDialog>
  <div class="storeBac">
    <div class="pb-5rem">
      <div class="max-w-1110px m-auto pt-180px ps-5 pe-5 relative z-2">
        <div class="mb-3">
          <h1 class="m-0 mb-2 text-center font-size-33px md-font-size-48px slogan">
            PMatch是你事業上的全能助手 !
          </h1>
          <h3 class="m-0 font-size-20px md-font-size-26px text-center subSlogan">
            輕鬆完成帳務整合與合法報稅、一站管理會員資料&交易數據、同時讓你的廣告被看見，<br>讓對的人找到你
          </h3>
        </div>
      </div>
    </div>
    <div class="pb-5rem">
      <div class="max-w-1110px m-auto ps-5 pe-5 relative z-2">
        <div class="md-flex">
          <div class="w-100%">
            <div class="matchBox">
              <div class="matchContent">
                <div class="flex justify-center pb-3">
                  <el-statistic :value="matchValue1" />
                  <span class="plus">+</span>
                </div>
                <div class="matchDetail">
                  <span class="m-0 md-block inline color-#fff text-center w-100%">
                    已經促成"百萬筆"
                  </span>
                  <span class="m-0 md-block inline color-#fff text-center w-100%">
                    以上的媒合
                  </span>
                </div>
              </div>
            </div>
          </div>
          <div class="w-100%">
            <div class="matchBox">
              <div class="matchContent">
                <div class="flex justify-center pb-3">
                  <el-statistic :value="matchValue3" />
                  <span class="plus">+</span>
                </div>
                <div class="matchDetail">
                  <span class="m-0 md-block inline color-#fff text-center md-w-100%">
                    已幫助"三萬+"
                  </span>
                  <span class="m-0 md-block inline color-#fff text-center md-w-100%">
                    位玩家完成媒合
                  </span>
                </div>
              </div>
            </div>
          </div>
          <div class="w-100%">
            <div class="matchBox">
              <div class="matchContent">
                <div class="flex justify-center pb-3">
                  <el-statistic :value="matchValue4" />
                  <span class="plus">+</span>
                </div>
                <div class="matchDetail">
                  <span class="m-0 md-block inline color-#fff text-center md-w-100%">
                    已攔截"二百多個"
                  </span>
                  <span class="m-0 md-block inline color-#fff text-center md-w-100%">
                    高風險銀行帳戶
                  </span>
                </div>
              </div>
            </div>
          </div>
          <div class="w-100%">
            <div class="matchBox">
              <div class="matchContent">
                <div class="flex justify-center pb-3">
                  <el-statistic :value="matchValue5" />
                  <span class="plus">+</span>
                </div>
                <div class="matchDetail">
                  <span class="m-0 md-block inline color-#fff text-center md-w-100%">
                    已有"二十多個"遊戲平台
                  </span>
                  <span class="m-0 md-block inline color-#fff text-center md-w-100%">
                    在PMatch上交易
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <!-- 數據分析 -->
    <div class="pb-5rem ">
      <div class="max-w-1110px m-auto ps-5 pe-5 relative z-2 md-flex">
        <!-- 甜甜圈圖 -->
        <div class="h-400px md-w-50% w-100% md:mb-0 mb-4rem d-flex justify-center items-center">
          <svg viewBox="80 10 250 250" xmlns="http://www.w3.org/2000/svg" height="100%" width="100%">
            <defs>
              <linearGradient id="paint0_linear_11_447" x1="0" y1="19.7511" x2="162.002" y2="19.7511"
                gradientUnits="userSpaceOnUse">
                <stop stopColor="#B0B0E7" />
                <stop offset="1" stopColor="white" />
              </linearGradient>
              <linearGradient id="paint0_linear_9_437" x1="-0.000305176" y1="22.847" x2="165.074" y2="22.847"
                gradientUnits="userSpaceOnUse">
                <stop stopColor="white" />
                <stop offset="1" stopColor="#B0B0E7" />
              </linearGradient>
              <linearGradient id="paint0_linear_0_2" x1="75" y1="0" x2="75" y2="37" gradientUnits="userSpaceOnUse">
                <stop stop-color="white" />
                <stop offset="1" stop-color="#9E77E6" />
              </linearGradient>
            </defs>

            <!-- 圓環圖 -->
            <g transform="translate(75, 10)">
              <!-- 黃色圓弧 (45%) - 從12點鐘開始 -->
              <circle cx="125" cy="125" r="90" fill="none" stroke="#ffd233" stroke-width="15"
                :stroke-dasharray="yellowStrokeDasharray" stroke-dashoffset="0" transform="rotate(-90 125 125)" />

              <!-- 紫色圓弧 (55%) - 接在黃色後面 -->
              <circle cx="125" cy="125" r="90" fill="none" stroke="#9b6dd6" stroke-width="15"
                :stroke-dasharray="purpleStrokeDasharray" :stroke-dashoffset="purpleStrokeDashoffset"
                transform="rotate(-90 125 125)" />

              <g>
                <rect x="85" y="98" width="80" height="23" rx="12" fill="#D9D9D9" fill-opacity="0.1" />
                <rect x="85" y="98" width="80" height="23" rx="12" stroke="url(#paint0_linear_0_2)"
                  stroke-opacity="0.5" fill="none" />
                <text x="125" y="115" text-anchor="middle" fill="white" font-size="14" opacity="0.8">
                  週交易量
                </text>
              </g>
              <!-- 中心文字 -->

              <text x="125" y="140" text-anchor="middle" fill="white" font-size="20" font-weight="bold">
                {{ weeklyData.toLocaleString() }}
              </text>
            </g>

            <!-- 黃色提示框（左側） -->
